def gate_fingerprint(cells_by_dc: Mapping[tuple[str, str], "list"], k: int) -> GatingVerdict:
    """Critic #3 non-empty/finite gating for G.

    FAILS (not a vacuous pass) when: no cells at all; any (driver, channel) does
    not carry exactly ``k`` cells; any *resolved* cell has a non-finite mean/sigma;
    or every cell is unresolved (no signal recovered anywhere).
    """
    if not cells_by_dc:
        return GatingVerdict(False, {"n_groups": 0}, "no fingerprint cells written")
    n_cells = 0
    n_resolved = 0
    problems: list[str] = []
    for (driver, channel), cells in cells_by_dc.items():
        if len(cells) != k:
            problems.append(f"{driver}/{channel}: {len(cells)} cells != k={k}")
            continue
        for c in cells:
            n_cells += 1
            if getattr(c, "status", None) == "resolved":
                n_resolved += 1
                if not (is_finite_number(c.mean) and is_finite_number(c.sigma)):
                    problems.append(
                        f"{driver}/{channel}/{c.class_id}: resolved but non-finite "
                        f"mean={c.mean!r} sigma={c.sigma!r}"
                    )
    if n_resolved == 0:
        problems.append("no resolved cells anywhere (vacuous)")
    passed = not problems
    return GatingVerdict(
        passed,
        {"n_groups": len(cells_by_dc), "n_cells": n_cells, "n_resolved": n_resolved, "k": k},
        "; ".join(problems) if problems else "k cells per group, resolved finite",
    )


def run_stage_h(
    fingerprint_store: Any,
    observables_db: str,
    vocabulary: Any,
    circuit: str,
    drivers: "Sequence[str]",  # noqa: F821
    *,
    year: int,
    session_type: str,
    as_of_round: int,
    map_version: str | None,
) -> list[dict[str, Any]]:
    """Join stage: compose E's field-reference fingerprint with each driver's G cells."""
    from src.physics.fingerprint.address import DEFAULT_WHAT_MEASURE, FINGERPRINT_CHANNELS
    from src.physics.fingerprint.join import join_weekend_prior
    from src.physics.utilization.reference_utilization_store import ReferenceUtilizationStore

    if not map_version:
        raise ValueError(
            f"run_stage_h: map_version is required (got {map_version!r}) -- the "
            f"reference_laps field row for {circuit!r} carries no map_version"
        )
    ref = ReferenceUtilizationStore(observables_db, must_exist=True)
    composition = ref.get(year, circuit, session_type, map_version).fingerprint
    records: list[dict[str, Any]] = []
    for driver in drivers:
        for channel in FINGERPRINT_CHANNELS:
            cells = fingerprint_store.get_fingerprint(
                driver, vocabulary.rules_era, vocabulary, channel, DEFAULT_WHAT_MEASURE,
            )
            prior = join_weekend_prior(
                composition, cells, vocabulary,
                as_of_round=as_of_round, map_version=map_version,
            )
            records.append({
                "driver": driver,
                "channel": channel,
                "mean": prior.mean,
                "scale": prior.prior.scale if prior.prior is not None else None,
                "nu": prior.prior.nu if prior.prior is not None else None,

